#[cfg(test)]
mod client_write_tests {
    use bytes::Bytes;
    use hex_literal::hex;
    use onc_rpc::{auth::AuthFlavor, CallBody, RpcMessage};

    use crate::nfs4_proto::xdr::{
        bitmap4, bitmap_inner, nfs_argop4, nfs_fh4, nfs_resop4, nfsstat4, offset4, stable_how4,
        stateid4, utf8str_cs, COMPOUND4args, GETATTR4args, GETFH4res, GETFH4resok, PUTFH4args,
        PUTFH4res, Serialisable, WRITE4args,
    };

    #[test]
    fn compound_write_1024_bytes() {
        let fh_id = nfs_fh4(Bytes::from(
            hex!("8000000000671ea47e0000000000000000000000000000006501").as_slice(),
        ));
        let data = Bytes::from(hex!("").as_slice());
        let stateid_other = Bytes::from(hex!("000000000000000000000064").as_slice());
        let op_putfh = PUTFH4args { object: fh_id };

        let op_write = WRITE4args {
            stateid: stateid4 {
                seqid: 1,
                other: stateid_other,
            },
            offset: offset4(0),
            stable: stable_how4::UNSTABLE4,
            data: data,
        };

        let op_getattr = GETATTR4args {
            attr_request: bitmap4(vec![bitmap_inner(0x00000018), bitmap_inner(0x00300000)]),
        };

        let compound = COMPOUND4args {
            tag: utf8str_cs(String::from("")),
            minorversion: 0,
            argarray: vec![
                nfs_argop4::OP_PUTFH(op_putfh),
                nfs_argop4::OP_WRITE(op_write),
                nfs_argop4::OP_GETATTR(op_getattr),
            ],
        };
        let auth_null: AuthFlavor<&[u8]> = AuthFlavor::AuthNone(None);

        let payload = compound;
        use bytes::BytesMut;
        let mut buf = BytesMut::with_capacity(1024);
        payload.serialize(&mut buf);

        assert_eq!(*buf, hex!(""));

        let call_body: CallBody<&[u8], Bytes> =
            CallBody::new(100003, 4, 1, auth_null.clone(), auth_null, buf.into());

        let msg = RpcMessage::new(0x8d90f0a9, onc_rpc::MessageType::Call(call_body));
    }

    #[test]
    fn serialize_a_thing() {
        use bytes::BytesMut;
        let mut buf = BytesMut::with_capacity(1024);

        let res = PUTFH4res {
            status: nfsstat4::NFS4ERR_ACCESS,
        };

        res.serialize(&mut buf);
        assert_eq!(*buf, hex!("0000000d"));
    }

    #[test]
    fn serialize_b_thing() {
        use bytes::BytesMut;
        let mut buf = BytesMut::with_capacity(1024);

        let nfs = GETFH4resok {
            object: nfs_fh4(Bytes::from("125763")),
        };
        let res = nfs_resop4::OP_GETFH(GETFH4res::NFS4_OK(nfs));
        res.serialize(&mut buf);
        assert_eq!(*buf, hex!("0000000a00000000000000063132353736330000"));
    }
}
